package io.knowledgebrain.activity;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1;import io.knowledgebrain.contracts.learning.githubevidence.v1.*;
class GitHubLearningActivityTest extends ActivityFixtures {
 @Test void bothNewStreamsRemainPrivateLearningAndUseExactHistoricalTargets(){for(String kind:List.of("GITHUB_EVIDENCE","GITHUB_EVIDENCE_SESSION")){var raw=wire(kind,id());var e=ActivityEvent.decode(ActivityEvent.TOPICS.get(kind),raw);assertEquals("learning",ActivityEvent.group(kind));assertTrue(GitHubLearningActivity.target(e));assertNotNull(e.roadmapId());assertNotNull(e.nodeId());assertNull(e.claim());ActivityEvent.transport(ActivityEvent.TOPICS.get(kind),raw,e.aggregateId().toString(),headers(e));var p=ActivityQueryTest.params("kind",kind);var query=ActivityQuery.parse(e.spaceId(),p);p.put("before",new String[]{query.cursor(e)});assertThrows(RuntimeException.class,()->ActivityQuery.parse(id(),p));p.put("kind",new String[]{"STUDY_SESSION"});assertThrows(RuntimeException.class,()->ActivityQuery.parse(e.spaceId(),p));}}
 @Test void wrongPrivacyMutableCommitSpoofedUrlAndSourceVersionCannotProject()throws Exception{var e=RoadmapEventEnvelopeV1.parseFrom(wire("GITHUB_EVIDENCE",id()));var p=GitHubEvidenceChangedPayloadV1.parseFrom(e.getPayload());for(var bad:List.of(p.toBuilder().setVisibility("PUBLIC"),p.toBuilder().setCommitVersion(2),p.toBuilder().setUrl("https://evil.test/"),p.toBuilder().setVersion(0),p.toBuilder().setUpdatedAt("2020-01-01T00:00:00Z"),p.toBuilder().setEvidenceId(id().toString()))){assertThrows(RuntimeException.class,()->ActivityEvent.decode("learning.github-evidence.v1",e.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));}assertDoesNotThrow(()->ActivityEvent.decode("learning.github-evidence.v1",e.toBuilder().setPayload(p.toBuilder().setAuthorLogin("dependabot[bot]").build().toByteString()).build().toByteArray()));}
 @Test void sessionKindAndIntervalAreValidated()throws Exception{var e=RoadmapEventEnvelopeV1.parseFrom(wire("GITHUB_EVIDENCE_SESSION",id()));var p=GitHubEvidenceSessionChangedPayloadV1.parseFrom(e.getPayload());for(var bad:List.of(p.toBuilder().setEvidenceKind("NOTE"),p.toBuilder().setSessionVersion(0),p.toBuilder().setDurationSeconds(61),p.toBuilder().setState("UNLINKED"))){assertThrows(RuntimeException.class,()->ActivityEvent.decode("learning.github-evidence-session.v1",e.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));}}
}
